insert into public.pulse_challenge_templates (id, code, title, description, category, difficulty, points, answer_type, options, scoring_rule, required_facts, active, priority, cooldown_days, tags)
select 'cht_' || lower(code), code, title, description, category, difficulty, points, "answerType", options, rule, array['home_score','away_score']::text[], true, priority, cooldown, array(select jsonb_array_elements_text(tags))
from jsonb_to_recordset($json$[{"code":"BOTH_GTE_4","title":"¿Ambos equipos llegarán a 4 o más?","description":"Se corrige con el marcador final.","category":"ofensiva","difficulty":"hard","points":6,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"both_gte","n":4},"priority":0,"cooldown":2,"tags":["ofensiva"]},{"code":"BOTH_GTE_5","title":"¿Ambos equipos anotarán 5 o más?","description":"Se corrige con el marcador final.","category":"ofensiva","difficulty":"expert","points":10,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"both_gte","n":5},"priority":0,"cooldown":2,"tags":["ofensiva"]},{"code":"BOTH_LTE_2","title":"¿Ningún equipo pasa de 2 carreras?","description":"Se corrige con el marcador final.","category":"defensiva","difficulty":"expert","points":8,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"both_lte","n":2},"priority":0,"cooldown":2,"tags":["defensiva"]},{"code":"BOTH_LTE_3","title":"¿Ningún equipo llega a 4 carreras?","description":"Se corrige con el marcador final.","category":"defensiva","difficulty":"hard","points":6,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"both_lte","n":3},"priority":0,"cooldown":2,"tags":["defensiva"]}]$json$::jsonb) as t(code text, title text, description text, category text, difficulty text, points int, "answerType" text, options jsonb, rule jsonb, priority int, cooldown int, tags jsonb)
on conflict (code) do nothing;